    content:'لا يوصف المناخ من طقس يوم أو موسم واحد؛ بل من بيانات طويلة المدى. يمكن أن يتغير المناخ لأسباب طبيعية وبسبب تغير تراكيز غازات الدفيئة الناتج عن أنشطة بشرية. تؤثر الجبال في الهطول وقد يتكون ظل مطر في الجهة الواقعة خلفها بالنسبة للرياح الرطبة.',
